//! Firmware entry point: initialize the HAL, then prove the chip boots, the logger works, and the
//! network comes up.
//!
//! Everything below the entry point is generated by `esp-generate`; see AGENTS.md for what that means
//! when the generator is re-run. What is added here should be the proof of concept itself, not the
//! scaffolding around it.

#![no_std]
#![no_main]
#![deny(
    clippy::mem_forget,
    reason = "mem::forget is generally not safe to do with esp_hal types, especially those \
    holding buffers for the duration of a data transfer."
)]
#![deny(clippy::large_stack_frames)]

use defmt::info;
use embassy_executor::Spawner;
use embassy_time::{Duration, Timer};
use esp_backtrace as _;
use esp_hal::clock::CpuClock;
use esp_hal::main;
use esp_hal::ram;
use esp_hal::timer::timg::TimerGroup;
use esp_println as _;
// The C library's `memchr`, which `MbedTLS` calls from `x509.c`. It is named here rather than left to
// the linker because a dependency nothing in Rust refers to is not linked at all, so without this the
// firmware builds until the last step and then fails with `undefined symbol: memchr`.
use tinyrlibc as _;

use esp_poc::status;

// This creates a default app-descriptor required by the esp-idf bootloader.
// For more information see: <https://docs.espressif.com/projects/esp-idf/en/stable/esp32/api-reference/system/app_image_format.html#application-description>
esp_bootloader_esp_idf::esp_app_desc!();

#[allow(
    clippy::large_stack_frames,
    reason = "it's not unusual to allocate larger buffers etc. in main"
)]
#[main]
async fn main(spawner: Spawner) -> ! {
    // generator version: 1.4.0
    // generator parameters: one per chip, in the block below that reserves its pins.
    //
    // The generator emits a reserved-pin list per chip and there is no way to ask it for both at once,
    // so these two blocks are what two branches would have said here, kept in one file and one chip
    // apart. Each is what `esp-generate` produces for its board; the pins are the ones in use by
    // something on the module, and a binding's only job is to be the move that reserves the
    // peripheral — which is why `no_effect_underscore_binding` is allowed in `[lints.clippy]` and not
    // here.
    let config = esp_hal::Config::default().with_cpu_clock(CpuClock::max());
    let peripherals = esp_hal::init(config);

    #[cfg(feature = "esp32c6")]
    {
        // generator parameters: -o esp32c6 -o stack-smashing-protection -o ci -o agents -o defmt -o
        // esp-backtrace -o wokwi -o vscode -o 1.98.1-x86_64-pc-windows-msvc -o esp32c6-mini-1
        //
        // The following pins are used to bootstrap the chip. They are available
        // for use, but check the datasheet of the module for more information on them.
        // - GPIO4
        // - GPIO5
        // - GPIO8
        // - GPIO9
        // - GPIO15
        // These GPIO pins are in use by some feature of the module and should not be used.
        let _gpio24 = peripherals.GPIO24;
        let _gpio25 = peripherals.GPIO25;
        let _gpio26 = peripherals.GPIO26;
        let _gpio27 = peripherals.GPIO27;
        let _gpio28 = peripherals.GPIO28;
        let _gpio29 = peripherals.GPIO29;
        let _gpio30 = peripherals.GPIO30;
    }

    #[cfg(feature = "esp32c3")]
    {
        // generator parameters: -o esp32c3 -o unstable-hal -o alloc -o wifi -o embassy -o
        // stack-smashing-protection -o defmt -o esp-backtrace -o wokwi -o vscode -o agents -o
        // esp32c3-mini-1
        //
        // The following pins are used to bootstrap the chip. They are available
        // for use, but check the datasheet of the module for more information on them.
        // - GPIO2
        // - GPIO8
        // - GPIO9
        // These GPIO pins are in use by some feature of the module and should not be used.
        let _gpio11 = peripherals.GPIO11;
        let _gpio12 = peripherals.GPIO12;
        let _gpio13 = peripherals.GPIO13;
        let _gpio14 = peripherals.GPIO14;
        let _gpio15 = peripherals.GPIO15;
        let _gpio16 = peripherals.GPIO16;
        let _gpio17 = peripherals.GPIO17;
    }

    // The radio and the network stack above it allocate, so this firmware is no longer heap-free.
    // The first heap takes the RAM the bootloader reclaimed; the second takes internal RAM. The
    // budget is now two heaps rather than one, because the TLS handshake in `src/report.rs` takes
    // about 32 KiB out of them at its peak — MbedTLS allocates a record buffer in each direction,
    // 16 KiB each by default — on top of whatever the radio is holding.
    esp_alloc::heap_allocator!(#[ram(reclaimed)] size: 64 * 1024);
    esp_alloc::heap_allocator!(size: 96 * 1024);

    // The entropy MbedTLS draws its key material from is enabled later, not here, so the two
    // peripherals travel into the reporting task. `src/tls.rs` says why the wait matters.

    // The radio needs a preemptive scheduler and will not start without one, so this has to come
    // before anything touches the radio. `FROM_CPU_INTR0` is how the scheduler is woken.
    let timg0 = TimerGroup::new(peripherals.TIMG0);
    esp_rtos::start(timg0.timer0, peripherals.FROM_CPU_INTR0);

    // Join the network in the background. The stack is what the greeting below reads the address
    // out of, and it is `Copy`, so handing a copy to the SNTP client below leaves it here.
    let stack = esp_poc::wifi::join(spawner, peripherals.WIFI);

    // With a network, ask a time server over it what time it is, and report what this chip is doing
    // to an HTTPS API. Both run in their own tasks and need no answer from here: until a time arrives
    // the greeting prints how long the chip has been up, and until the API answers, the reporter has
    // said nothing at all.
    if let Some(stack) = stack {
        esp_poc::ntp::sync(spawner, stack);
        esp_poc::report::start(spawner, stack, peripherals.RNG, peripherals.ADC1);
    }

    loop {
        // One call, one line, and every fact on it comes from a different task: the radio's state
        // from `wifi`, the time and where it came from from `clock`, and the address from the
        // network stack. `src/status.rs` is what puts them together, and `poc-report` decides how
        // they read — which is why the wording of this line is something a host can test and not
        // something assembled here.
        info!(
            "Hello world! {}",
            defmt::Display2Format(&status::report(stack))
        );

        Timer::after(Duration::from_millis(500)).await;
    }

    // for inspiration have a look at the examples at https://github.com/esp-rs/esp-hal/tree/esp-hal-v1.2.2/examples
}
